INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('6352aa56-67fc-470f-a23a-9bf0366b1caf', 'b2b2b2b2-3030-4000-8000-000000000002', 25, 'Dia 25 — Cicatrizes', 'Semana 4: Integrar', '{"pch": "Jesus mostrou suas cicatrizes\u2026 Elas n\u00e3o desapareceram \u2014 se tornaram testemunho.", "verse": "Jo 20,27", "lectio": "Leia Jo 20,24-29. Tom\u00e9 tocou as feridas.", "practice": "Agrade\u00e7a por uma cicatriz. Ela prova que voc\u00ea sobreviveu.", "question": "Que cicatrizes suas contam uma hist\u00f3ria de supera\u00e7\u00e3o?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;